import subprocess, http.server, threading, time, socket

def run_server(body_html, extra_routes=None):
    s=socket.socket(); s.bind(('127.0.0.1',0)); port=s.getsockname()[1]; s.close()
    body = body_html.encode() if isinstance(body_html,str) else body_html
    routes = extra_routes or {}
    class H(http.server.BaseHTTPRequestHandler):
        def log_message(self,*a): pass
        def do_GET(self):
            #print(f"GET {self.path}")
            if self.path=="/" or self.path=="/index.html":
                self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
            elif self.path in routes:
                b,c,ct = routes[self.path]
                self.send_response(c); self.send_header("Content-Type",ct); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
            elif self.path.startswith("/page"):
                # page without id
                b=b'<html><body>page no id</body></html>'; self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
            elif self.path.startswith("/pagewithid"):
                b=b'<html><body><div id="frag">hi</div></body></html>'; self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
            elif self.path.startswith("/"):
                if "bad" in self.path:
                    b=b'nf'; self.send_response(404); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
                else:
                    b=b'ok'; self.send_response(200); self.send_header("Content-Type","text/plain"); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
            else:
                b=b'nf'; self.send_response(404); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
    httpd=http.server.HTTPServer(("127.0.0.1",port),H)
    t=threading.Thread(target=httpd.serve_forever,daemon=True); t.start()
    time.sleep(0.1)
    return httpd, t, port

def run_muffet(*args):
    r=subprocess.run(['./executable']+list(args), capture_output=True, timeout=10)
    return r.returncode, r.stdout.decode(), r.stderr.decode()

tests = [
    ('<html><body><a href="/page#frag">x</a></body></html>', [], 'page no id, frag'),
    ('<html><body><a href="/pagewithid#frag">x</a></body></html>', [], 'page with id frag'),
    ('<html><body><a href="/page#other">x</a></body></html>', [], 'page no id other frag'),
    ('<html><body><a href="ftp://example.com/x">x</a></body></html>', [], 'ftp link'),
    ('<html><body><a href="http://127.0.0.1:9/bad">x</a></body></html>', [], 'unreachable link'),
    ('<html><body><a href="/bad#frag">x</a></body></html>', [], 'bad page + frag'),
    ('<html><body><a href="#frag">x</a></body></html>', ['-f'], 'ignore frag missing'),
    ('<html><body><a href="/page#frag">x</a></body></html>', ['-f'], 'ignore frag page'),
]

for html, extra, desc in tests:
    httpd,t,port = run_server(html)
    rc,out,err = run_muffet(*(extra+['--verbose', f'http://127.0.0.1:{port}/']))
    print(f"{desc} -> rc={rc} out={out.strip()!r} err={err.strip()!r}")
    # also json
    rc2,out2,err2 = run_muffet(*(extra+['--verbose','--format=json', f'http://127.0.0.1:{port}/']))
    print(f"  json: {out2.strip()!r}")
    httpd.shutdown(); httpd.server_close(); t.join(timeout=1)
