def run_server():
    s=socket.socket(); s.bind(('127.0.0.1',0)); port=s.getsockname()[1]; s.close()
    class H(http.server.BaseHTTPRequestHandler):
        def log_message(self,*a): pass
        def do_GET(self):
            print(f"GET {self.path}", flush=True)
            if self.path=="/" :
                body=b'<html><body><a href="/mid">mid</a></body></html>'
                self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
            elif self.path=="/mid":
                # mid is plain text containing link to /leaf, should it be followed?
                body=b'<html><body><a href="/leaf">leaf</a></body></html>'
                self.send_response(200); self.send_header("Content-Type","text/plain"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
            elif self.path=="/leaf":
                body=b'leaf'; self.send_response(200); self.send_header("Content-Type","text/plain"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
            else:
                b=b'nf'; self.send_response(404); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)
    httpd=http.server.HTTPServer(("127.0.0.1",port),H)
    t=threading.Thread(target=httpd.serve_forever,daemon=True); t.start()
    time.sleep(0.1)
    return httpd, t, port

def run_muffet(*args):
    r=subprocess.run(['./executable']+list(args), capture_output=True, timeout=10)
    return r.returncode, r.stdout.decode(), r.stderr.decode()

httpd,t,port = run_server()
for extra in [[],['--verbose'],['--verbose','--format=json']]:
    rc,out,err = run_muffet(*(extra+[f'http://127.0.0.1:{port}/']))
    print(f"{extra} rc={rc} out={out.strip()!r} err={err.strip()!r}")
httpd.shutdown(); httpd.server_close(); t.join(timeout=1)
