    s=socket.socket(); s.bind(('127.0.0.1',0)); port=s.getsockname()[1]; s.close()
    httpd=http.server.HTTPServer(("127.0.0.1",port),handler)
    t=threading.Thread(target=httpd.serve_forever,daemon=True); t.start()
    time.sleep(0.1)
    return httpd,t,port
def run(*args):
    r=subprocess.run(['./executable']+list(args), capture_output=True, timeout=15)
    return r.returncode, r.stdout.decode(), r.stderr.decode()

# Redirect tests
class HRedir(http.server.BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def do_GET(self):
        if self.path=="/" :
            body=b'<html><body><a href="/r1">r1</a><a href="/loop">loop</a><a href="/noloc">noloc</a><a href="/redir-external">ext</a></body></html>'
            self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
        elif self.path=="/r1":
            self.send_response(302); self.send_header("Location","/r2"); self.send_header("Content-Length","0"); self.end_headers()
        elif self.path=="/r2":
            self.send_response(302); self.send_header("Location","/final"); self.send_header("Content-Length","0"); self.end_headers()
        elif self.path=="/final":
            body=b'<html><body>final</body></html>'; self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
        elif self.path=="/loop":
            self.send_response(302); self.send_header("Location","/loop"); self.send_header("Content-Length","0"); self.end_headers()
        elif self.path=="/noloc":
            self.send_response(302); self.send_header("Content-Length","0"); self.end_headers()
        elif self.path=="/redir-external":
            self.send_response(302); self.send_header("Location","http://127.0.0.1:9/nonexist"); self.send_header("Content-Length","0"); self.end_headers()
        else:
            b=b'nf'; self.send_response(404); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)

