func progName() string {
	p := os.Args[0]
	if i := strings.LastIndex(p, "/"); i >= 0 {
		p = p[i+1:]
	}
	if i := strings.LastIndex(p, "\\"); i >= 0 {
		p = p[i+1:]
	}
	if p == "" {
		p = "executable"
	}
	return p
}

func printHelp() {
	fmt.Printf("Usage:\n  %s [options] <url>\n%s", progName(), helpBody)
}

func flagDisplayLong(short, long string) string {
	if short != "" {
		return fmt.Sprintf("-%s, --%s", short, long)
	}
	return fmt.Sprintf("--%s", long)
}

func main() {
	os.Exit(run())
}

func run() int {
	opts := &options{
		acceptedStatusCodes: "200..300",
		bufferSize: 4096,
		maxConnections: 512,
		maxConnectionsPerHost: 512,
		maxResponseBodySize: 10000000,
		format: "text",
		maxRedirections: 64,
		timeout: 10,
		color: "auto",
	}
	args := os.Args[1:]
	// parsing
	pos, errMsg := parseArgs(args, opts)
	if errMsg != "" {
		fmt.Fprintf(os.Stderr, "%s\n", errMsg)
		return 1
	}
	// help/version
	if opts.helpFlag {
		printHelp()
		return 0
	}
	if opts.versionFlag {
		fmt.Printf("%s\n", version)
		return 0
	}
	if len(pos) != 1 {
		fmt.Fprintf(os.Stderr, "invalid number of arguments\n")
		return 1
	}
	// validations in order: exclude, include, header, status, verbose+junit
	for _, pat := range opts.excludes {
		if _, err := regexp.Compile(pat); err != nil {
			fmt.Fprintf(os.Stderr, "error parsing regexp: %s: `%s`\n", err.Error(), pat)
			// Go's regexp error message: "error parsing regexp: missing closing ]: `[invalid`"
			// Our err.Error() already is "missing closing ]: `[invalid`", so prefix matches.
			return 1
		}
	}
	for _, pat := range opts.includes {
		if _, err := regexp.Compile(pat); err != nil {
			fmt.Fprintf(os.Stderr, "error parsing regexp: %s: `%s`\n", err.Error(), pat)
			return 1
		}
	}
	// header format: must contain :
	for _, h := range opts.headers {
		if !strings.Contains(h, ":") {
			fmt.Fprintf(os.Stderr, "invalid header format\n")
			return 1
		}
	}
	// status codes
	accepted, errStr := parseStatusCodes(opts.acceptedStatusCodes)
	if errStr != "" {
		fmt.Fprintf(os.Stderr, "%s\n", errStr)
		return 1
	}
	// determine final format
	finalFormat := opts.format
	if opts.jsonFlag {
		finalFormat = "json"
	} else if opts.junitFlag {
		finalFormat = "junit"
	}
	// verbose + junit check (only if verbose flag and finalFormat junit)
	if opts.verbose && finalFormat == "junit" {
		fmt.Fprintf(os.Stderr, "verbose option not supported for JUnit output\n")
		return 1
	}
	// determine verboseJson
	verboseJson := false
	if finalFormat == "json" {
		if opts.verbose {
			verboseJson = true
		} else if opts.expVerboseJson && opts.jsonFlag {
			verboseJson = true
		}
	}
	verboseText := opts.verbose

	urlStr := pos[0]

	// compile regexes
	var excludeRes []*regexp.Regexp
	for _, p := range opts.excludes {
		r, _ := regexp.Compile(p)
		excludeRes = append(excludeRes, r)
	}
	var includeRes []*regexp.Regexp
	for _, p := range opts.includes {
		r, _ := regexp.Compile(p)
		includeRes = append(includeRes, r)
	}
	// parse headers into map
	headerMap := make(map[string]string)
	headerNames := []string{} // to preserve? Actually need to send all; if duplicate names, last wins? Use map.
	for _, h := range opts.headers {
		parts := strings.SplitN(h, ":", 2)
		name := parts[0]
		val := ""
		if len(parts) == 2 {
			val = strings.TrimSpace(parts[1])
		}
		headerMap[name] = val
		// keep order? not needed
		_ = headerNames
	}

	c := &crawler{
		opts: opts,
		accepted: accepted,
		excludeRes: excludeRes,
		includeRes: includeRes,
		headerMap: headerMap,
		finalFormat: finalFormat,
		verboseText: verboseText,
		verboseJson: verboseJson,
	}
	// run crawl
	results, rootErr := c.crawl(urlStr)
	if rootErr != "" {
		fmt.Fprintf(os.Stderr, "failed to fetch root page: %s\n", rootErr)
		return 1
	}
	// check sitemap/robots already handled inside crawl? They return rootErr if fail
	// output
	hasError := false
	for _, pr := range results {
		for _, l := range pr.links {
			if l.isError {
				hasError = true
				break
			}
		}
		if hasError {
			break
		}
	}
	// Actually hasError should consider only displayed? No, any error in any page (including non-displayed? but all pages are in results). For non-verbose, results only contain pages with errors? Wait our crawl collects all pages; output filters. hasError should be true if any link error exists (regardless of verbose). Good.
	_ = hasError
	// output based on format
	useColor := false
	if opts.color == "always" {
		useColor = true
	} else if opts.color == "auto" {
		// check if stdout is tty
		fi, err := os.Stdout.Stat()
		if err == nil && (fi.Mode()&os.ModeCharDevice) != 0 {
			useColor = true
		}
	}
	if finalFormat == "text" {
		c.outputText(results, useColor, verboseText)
	} else if finalFormat == "json" {
		c.outputJSON(results, verboseJson)
	} else if finalFormat == "junit" {
		c.outputJUnit(results)
	}
	// exit code: 1 if any error, else 0. But what about root with no links and no errors? 0. Good.
	// Need to determine hasError correctly: check all links in results (including successes?).
	hasErr := false
	for _, pr := range results {
		for _, l := range pr.links {
			if l.isError {
				hasErr = true
				break
			}
		}
	}
	if hasErr {
		return 1
	}
	return 0
}

func parseStatusCodes(s string) (func(int) bool, string) {
	if s == "" {
		return nil, "invalid status code range: "
	}
	tokens := strings.Split(s, ",")
	type rng struct{ lo, hi int }
	var ranges []rng
	var singles []int
	for _, tok := range tokens {
		if tok == "" {
			return nil, "invalid status code range: "
		}
		if strings.Contains(tok, "..") {
			parts := strings.Split(tok, "..")
			if len(parts) != 2 {
				return nil, "invalid status code range: " + tok
			}
			// each part must be int, else "invalid status code: <part>"
			loStr, hiStr := parts[0], parts[1]
			lo, err1 := strconv.Atoi(loStr)
			if err1 != nil {
				// need to distinguish? For "200..", hi is "" => error "invalid status code: "
				// For "..200", lo is "" => error "invalid status code: "
				// Use loStr as is
				return nil, "invalid status code: " + loStr
			}
			hi, err2 := strconv.Atoi(hiStr)
			if err2 != nil {
				return nil, "invalid status code: " + hiStr
			}
			ranges = append(ranges, rng{lo, hi})
		} else {
			// single must be int, else "invalid status code range: <tok>"
			v, err := strconv.Atoi(tok)
			if err != nil {
				return nil, "invalid status code range: " + tok
			}
			singles = append(singles, v)
		}
	}
	fn := func(code int) bool {
		for _, v := range singles {
			if code == v {
				return true
			}
		}
		for _, r := range ranges {
			if code >= r.lo && code < r.hi {
				return true
			}
		}
		return false
	}
	return fn, ""
}

// parsing args
func parseArgs(args []string, opts *options) ([]string, string) {
	var pos []string
	i := 0
	n := len(args)
	// helper to check if arg is option (starts with - and len>1)
	isOpt := func(s string) bool {
		return len(s) > 1 && strings.HasPrefix(s, "-")
	}
	for i < n {
		arg := args[i]
		if arg == "--" {
			// rest are positional
			pos = append(pos, args[i+1:]...)
			break
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			pos = append(pos, arg)
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			// long
			eq := strings.Index(arg, "=")
			var name, val string
			hasVal := false
			if eq != -1 {
				name = arg[2:eq]
				val = arg[eq+1:]
				hasVal = true
			} else {
				name = arg[2:]
			}
			// find flag
			switch name {
			case "accepted-status-codes":
				if hasVal {
					opts.acceptedStatusCodes = val
					i++
				} else {
					if i+1 >= n {
						return nil, "expected argument for flag `--accepted-status-codes'"
					}
					next := args[i+1]
					if next == "--" {
						return nil, "expected argument for flag `--accepted-status-codes', but got double dash `--'"
					}
					if isOpt(next) {
						return nil, fmt.Sprintf("expected argument for flag `--accepted-status-codes', but got option `%s'", next)
					}
					opts.acceptedStatusCodes = next
					i += 2
				}
			case "buffer-size":
				disp := "-b, --buffer-size"
				var s string
				if hasVal {
					s = val
					if err := setInt(&opts.bufferSize, s, disp); err != "" {
						return nil, err
					}
					i++
				} else {
					if i+1 >= n {
						return nil, fmt.Sprintf("expected argument for flag `%s'", disp)
					}
					next := args[i+1]
					if next == "--" {
						return nil, fmt.Sprintf("expected argument for flag `%s', but got double dash `--'", disp)
					}
					if isOpt(next) {
						// try parse as int, if success consume, else error
						if _, err := strconv.ParseInt(next, 10, 64); err == nil {
							if err2 := setInt(&opts.bufferSize, next, disp); err2 != "" {
								return nil, err2
							}
							i += 2
						} else {
							return nil, fmt.Sprintf("expected argument for flag `%s', but got option `%s'", disp, next)
						}
					} else {
