func progName() string {
	p := os.Args[0]
	if i := strings.LastIndex(p, "/"); i >= 0 {
		p = p[i+1:]
	}
	if i := strings.LastIndex(p, "\\"); i >= 0 {
		p = p[i+1:]
	}
	if p == "" {
