func parseStatusCodes(s string) (func(int) bool, string) {
	if s == "" {
		return nil, "invalid status code range: "
	}
	tokens := strings.Split(s, ",")
	type rng struct{ lo, hi int }
	var ranges []rng
	var singles []int
	for _, tok := range tokens {
		if tok == "" {
			return nil, "invalid status code range: "
		}
		if strings.Contains(tok, "..") {
			parts := strings.Split(tok, "..")
			if len(parts) != 2 {
				return nil, "invalid status code range: " + tok
			}
			// each part must be int, else "invalid status code: <part>"
			loStr, hiStr := parts[0], parts[1]
			lo, err1 := strconv.Atoi(loStr)
			if err1 != nil {
				// need to distinguish? For "200..", hi is "" => error "invalid status code: "
				// For "..200", lo is "" => error "invalid status code: "
				// Use loStr as is
				return nil, "invalid status code: " + loStr
			}
			hi, err2 := strconv.Atoi(hiStr)
			if err2 != nil {
				return nil, "invalid status code: " + hiStr
			}
			ranges = append(ranges, rng{lo, hi})
		} else {
			// single must be int, else "invalid status code range: <tok>"
			v, err := strconv.Atoi(tok)
			if err != nil {
				return nil, "invalid status code range: " + tok
			}
			singles = append(singles, v)
		}
	}
	fn := func(code int) bool {
		for _, v := range singles {
			if code == v {
				return true
			}
		}
		for _, r := range ranges {
			if code >= r.lo && code < r.hi {
				return true
			}
		}
		return false
	}
	return fn, ""
}

// parsing args
func parseArgs(args []string, opts *options) ([]string, string) {
	var pos []string
	i := 0
	n := len(args)
	// helper to check if arg is option (starts with - and len>1)
	isOpt := func(s string) bool {
		return len(s) > 1 && strings.HasPrefix(s, "-")
	}
	for i < n {
		arg := args[i]
		if arg == "--" {
			// rest are positional
			pos = append(pos, args[i+1:]...)
			break
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			pos = append(pos, arg)
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			// long
			eq := strings.Index(arg, "=")
			var name, val string
			hasVal := false
