				case 'r':
					rest := chars[j+1:]
					if strings.HasPrefix(rest, "=") {
						rest = rest[1:]
					}
					if rest != "" {
						if err := setInt(&opts.maxRedirections, rest, "-r, --max-redirections"); err != "" {
							return nil, err
						}
						j = len(chars)
					} else {
						if i+1 >= n {
							return nil, "expected argument for flag `-r, --max-redirections'"
						}
						next := args[i+1]
						if next == "--" {
							return nil, "expected argument for flag `-r, --max-redirections', but got double dash `--'"
						}
						if isOpt(next) {
							if _, err := strconv.ParseInt(next, 10, 64); err == nil {
								if err2 := setInt(&opts.maxRedirections, next, "-r, --max-redirections"); err2 != "" {
									return nil, err2
								}
								i++
								j = len(chars)
							} else {
								return nil, fmt.Sprintf("expected argument for flag `-r, --max-redirections', but got option `%s'", next)
							}
						} else {
							if err := setInt(&opts.maxRedirections, next, "-r, --max-redirections"); err != "" {
								return nil, err
							}
							i++
							j = len(chars)
						}
					}
					j = len(chars)
				case 't':
					rest := chars[j+1:]
					if strings.HasPrefix(rest, "=") {
						rest = rest[1:]
					}
					if rest != "" {
						if err := setInt(&opts.timeout, rest, "-t, --timeout"); err != "" {
							return nil, err
						}
						j = len(chars)
					} else {
						if i+1 >= n {
							return nil, "expected argument for flag `-t, --timeout'"
						}
						next := args[i+1]
						if next == "--" {
							return nil, "expected argument for flag `-t, --timeout', but got double dash `--'"
						}
						if isOpt(next) {
							if _, err := strconv.ParseInt(next, 10, 64); err == nil {
								if err2 := setInt(&opts.timeout, next, "-t, --timeout"); err2 != "" {
									return nil, err2
								}
								i++
								j = len(chars)
							} else {
								return nil, fmt.Sprintf("expected argument for flag `-t, --timeout', but got option `%s'", next)
							}
						} else {
							if err := setInt(&opts.timeout, next, "-t, --timeout"); err != "" {
								return nil, err
							}
							i++
							j = len(chars)
						}
					}
					j = len(chars)
				case 'v':
					// bool, check for =?
					rest := chars[j+1:]
					if strings.HasPrefix(rest, "=") {
						return nil, "bool flag `-v, --verbose' cannot have an argument"
					}
					if rest != "" {
						// rest are additional flags? e.g., -vfoo => v then foo? But -v takes no arg, so remaining should be parsed as flags.
						// Our loop will continue with j++ and process next char as flag. So just set verbose and continue.
						opts.verbose = true
						j++
						// continue loop to process rest chars as flags
					} else {
						opts.verbose = true
						j++
					}
				case 'h':
					rest := chars[j+1:]
					if strings.HasPrefix(rest, "=") {
						return nil, "bool flag `-h, --help' cannot have an argument"
					}
					if rest != "" {
						opts.helpFlag = true
						// remaining chars are flags? e.g., -hfoo => h then f then o? Actually -hfoo should process f and o after.
						// So set help and continue.
						j++
					} else {
						opts.helpFlag = true
						j++
					}
				default:
					return nil, fmt.Sprintf("unknown flag `%c'", ch)
				}
				if consumed {
					break
				}
			}
			i++
		}
	}
	return pos, ""
}

func setInt(dst *int, s, disp string) string {
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing %q: invalid syntax", disp, s)
		// Note: Go's error for empty is `parsing ""` etc. Our s may be "".
		// For values like "1.5", error is `invalid syntax` as well.
		// Need to match exactly: for "abc", message is `strconv.ParseInt: parsing "abc": invalid syntax`
		// Our fmt matches.
	}
	*dst = int(v)
	return ""
}

func setUint(dst *uint, s, disp string) string {
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		// For "-1", error is `parsing "-1": invalid syntax`? Actually ParseUint for "-1" gives `invalid syntax` as well.
		return fmt.Sprintf("invalid argument for flag `%s' (expected uint): strconv.ParseUint: parsing %q: invalid syntax", disp, s)
	}
	*dst = uint(v)
	return ""
}

