func computeDialAddr(u *url.URL, opts *options) string {
	// For direct, resolve hostname to IP if needed, else use host:port
	// For proxy case, return proxy hostPort
	if opts.proxy != "" {
		p := opts.proxy
		var hp string
		if strings.Contains(p, "://") {
			if uu, err := url.Parse(p); err == nil {
				sl := strings.ToLower(uu.Scheme)
				if sl == "http" || sl == "https" {
					hp = uu.Host
				}
			}
		} else {
			hp = p
		}
		if hp != "" {
			if _, _, err := net.SplitHostPort(hp); err == nil {
				_, pt, _ := net.SplitHostPort(hp)
				if _, err2 := strconv.Atoi(pt); err2 == nil {
					return hp
				}
			}
		}
	}
	// direct
	host := u.Hostname()
	port := u.Port()
	if port == "" {
		if strings.ToLower(u.Scheme) == "https" {
			port = "443"
		} else {
			port = "80"
		}
	}
	if net.ParseIP(host) != nil {
		return net.JoinHostPort(host, port)
	}
	// resolve via system? For error prefix, use IP if resolvable, else host:port?
	ips, err := net.LookupIP(host)
	if err == nil && len(ips) > 0 {
		return net.JoinHostPort(ips[0].String(), port)
	}
	return net.JoinHostPort(host, port)
}
