			}
			ips, err := net.DefaultResolver.LookupIP(ctx, "ip", host)
			if err != nil {
				return nil, err
			}
			if len(ips) == 0 {
				return nil, fmt.Errorf("lookup %s: no such host", host)
			}
			ipStr := ips[0].String()
			dialAddr := net.JoinHostPort(ipStr, port)
