	c.client = &http.Client{
		Transport: tr,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}
	if c.opts.maxConnections < 0 {
		c.sem = make(chan struct{}, c.opts.maxConnections)
	} else if c.opts.maxConnections == 0 {
		c.sem = make(chan struct{}, 0)
	} else {
		c.sem = make(chan struct{}, c.opts.maxConnections)
	}
	c.hostSems = make(map[string]chan struct{})
	return nil
}

func getSystemDNS() string {
	data, err := os.ReadFile("/etc/resolv.conf")
	if err != nil {
		return "10.0.0.2:53"
	}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "nameserver") {
			parts := strings.Fields(line)
			if len(parts) >= 2 {
				ip := parts[1]
				if !strings.Contains(ip, ":") {
					// check if contains port?
					if _, _, err := net.SplitHostPort(ip); err == nil {
						return ip
					}
					return ip + ":53"
				}
				return ip
			}
		}
	}
	return "10.0.0.2:53"
}

func (c *crawler) getHostSem(host string) chan struct{} {
	c.hostMu.Lock()
	defer c.hostMu.Unlock()
	if s, ok := c.hostSems[host]; ok {
		return s
	}
	limit := c.opts.maxConnectionsPerHost
	if limit < 0 {
		limit = 0
		// will panic on make? For negative per-host, what happens? Not tested. Assume same as global: panic.
		// To replicate, make with negative will panic.
		s := make(chan struct{}, limit)
		c.hostSems[host] = s
		return s
	}
	if limit == 0 {
		s := make(chan struct{}, 0)
		c.hostSems[host] = s
		return s
	}
	s := make(chan struct{}, limit)
	c.hostSems[host] = s
	return s
}

func (c *crawler) throttle() {
	if c.opts.rateLimit <= 0 {
		return
	}
	c.rateMu.Lock()
	defer c.rateMu.Unlock()
	now := time.Now()
	interval := time.Second / time.Duration(c.opts.rateLimit)
	// lastReq stored as nano
	last := time.Unix(0, c.lastReq)
	if !last.IsZero() {
		elapsed := now.Sub(last)
		if elapsed < interval {
			time.Sleep(interval - elapsed)
			now = time.Now()
		}
	}
	c.lastReq = now.UnixNano()
}

