	"sync"
)

func (c *crawler) crawl(rootStr string) ([]pageResult, string) {
	if err := c.setupClient(); err != nil {
		return nil, err.Error()
	}
	rootURL, err := url.Parse(rootStr)
	if err != nil {
		return nil, err.Error()
	}
	schemeLower := strings.ToLower(rootURL.Scheme)
	if rootURL.Scheme == "" {
		return nil, "missing port in address"
	}
	if schemeLower != "http" && schemeLower != "https" {
		return nil, fmt.Sprintf("unsupported protocol %q. http and https are supported", rootURL.Scheme)
	}
	if rootURL.Host == "" {
		return nil, "missing port in address"
	}
	if rootURL.Hostname() == "" && rootURL.Host != "" {
		defPort := "80"
		if schemeLower == "https" {
			defPort = "443"
		}
		dialAddr := rootURL.Host + ":" + defPort
		return nil, fmt.Sprintf("address %s: too many colons in address", dialAddr)
	}
	rootFetchURL := *rootURL
	rootFetchURL.Fragment = ""
	canonicalRootStripped := rootFetchURL.String()
	status, header, body, finalURL, errStr, _ := c.fetchWithRetriesFull(rootFetchURL.String(), "")
	if errStr != "" {
		return nil, errStr
	}
	_ = status
	ct := header.Get("Content-Type")
	if !isHTMLContentType(ct) {
		return nil, "root page has invalid content type"
	}
	if c.opts.followRobots {
		robotsURL := &url.URL{Scheme: rootURL.Scheme, Host: rootURL.Host, Path: "/robots.txt"}
		_, hdr2, b2, _, e2, _ := c.fetchWithRetriesFull(robotsURL.String(), "")
		if e2 != "" {
			return nil, fmt.Sprintf("failed to fetch robots.txt: %s", e2)
		}
		_ = hdr2
		c.robotsDisallow = parseRobots(string(b2))
	}
	if c.opts.followSitemap {
		sitemapURL := &url.URL{Scheme: rootURL.Scheme, Host: rootURL.Host, Path: "/sitemap.xml"}
		_, _, _, _, e2, _ := c.fetchWithRetriesFull(sitemapURL.String(), "")
		if e2 != "" {
			return nil, fmt.Sprintf("failed to GET sitemap.xml: %s", e2)
		}
	}
	c.visited = make(map[string]bool)
	c.results = []pageResult{}
	finalStripped := stripFragment(finalURL.String())
	c.visited[finalStripped] = true
	c.visited[canonicalRootStripped] = true
	queue := []workItem{{pageURL: finalURL.String(), body: body}}
	for len(queue) > 0 {
		item := queue[0]
		queue = queue[1:]
		pageURLStr := item.pageURL
		pageBody := item.body
		baseURL, _ := url.Parse(pageURLStr)
		rawLinks := extractLinks(pageBody, baseURL)
		type linkInfo struct {
			display  string
			stripped string
			fragment string
		}
		seen := make(map[string]bool)
		var infos []linkInfo
		type parseErrInfo struct {
			display string
			errStr  string
		}
		var parseErrs []parseErrInfo
		for _, raw := range rawLinks {
			rawTrim := strings.TrimSpace(raw)
			if rawTrim == "" {
				continue
			}
			parsedRaw, err := url.Parse(rawTrim)
			if err != nil {
				disp := rawTrim
				if !seen[disp] {
					seen[disp] = true
					parseErrs = append(parseErrs, parseErrInfo{display: disp, errStr: err.Error()})
				}
				continue
			}
			if parsedRaw.IsAbs() {
				sch := strings.ToLower(parsedRaw.Scheme)
				if sch != "http" && sch != "https" {
					continue
				}
			} else {
				if parsedRaw.Scheme != "" {
					sch := strings.ToLower(parsedRaw.Scheme)
					if sch != "http" && sch != "https" && sch != "" {
						continue
					}
				}
			}
			resolved := baseURL.ResolveReference(parsedRaw)
			sch2 := strings.ToLower(resolved.Scheme)
			if sch2 != "http" && sch2 != "https" {
				continue
			}
			disp := resolved.String()
			if !seen[disp] {
				seen[disp] = true
				infos = append(infos, linkInfo{display: disp, stripped: stripFragment(disp), fragment: resolved.Fragment})
			}
		}
		var filtered []linkInfo
		for _, inf := range infos {
			if c.shouldExclude(inf.display) {
				continue
			}
			if !c.shouldInclude(inf.display) {
				continue
			}
			filtered = append(filtered, inf)
		}
		var filteredParseErrs []parseErrInfo
		for _, pe := range parseErrs {
			if c.shouldExclude(pe.display) {
				continue
			}
			if !c.shouldInclude(pe.display) {
				continue
			}
			filteredParseErrs = append(filteredParseErrs, pe)
		}
		pageStripped := stripFragment(pageURLStr)
		var pageLinks []linkResult
		for _, pe := range filteredParseErrs {
			pageLinks = append(pageLinks, linkResult{url: pe.display, errStr: pe.errStr, isError: true})
		}
		var mu sync.Mutex
		var wg sync.WaitGroup
		var newWorks []workItem
		var newWorksMu sync.Mutex
		for _, inf := range filtered {
			wg.Add(1)
			go func(inf linkInfo) {
				defer wg.Done()
				if !c.opts.ignoreFragments && inf.fragment != "" && inf.stripped == pageStripped {
					if hasFragmentID(pageBody, inf.fragment) {
						mu.Lock()
						pageLinks = append(pageLinks, linkResult{url: inf.display, status: 200, isError: false})
						mu.Unlock()
					} else {
						mu.Lock()
						pageLinks = append(pageLinks, linkResult{url: inf.display, errStr: fmt.Sprintf("id #%s not found", inf.fragment), isError: true})
						mu.Unlock()
					}
					return
				}
				if c.opts.ignoreFragments {
					st, hdr, b, finalU, eStr, _ := c.fetchWithRetriesFull(inf.stripped, "")
					if eStr != "" {
						mu.Lock()
						pageLinks = append(pageLinks, linkResult{url: inf.display, errStr: eStr, isError: true})
						mu.Unlock()
					} else {
						mu.Lock()
						pageLinks = append(pageLinks, linkResult{url: inf.display, status: st, isError: false})
						mu.Unlock()
						c.tryQueue(finalU.String(), b, hdr, &newWorks, &newWorksMu)
					}
					return
				}
				if inf.fragment != "" {
					st, hdr, b, finalU, eStr, _ := c.fetchWithRetriesFull(inf.stripped, "")
					if eStr != "" {
						mu.Lock()
						pageLinks = append(pageLinks, linkResult{url: inf.display, errStr: eStr, isError: true})
						mu.Unlock()
						return
					}
					ct2 := hdr.Get("Content-Type")
					if isHTMLContentType(ct2) {
						if !hasFragmentID(b, inf.fragment) {
							mu.Lock()
							pageLinks = append(pageLinks, linkResult{url: inf.display, errStr: fmt.Sprintf("id #%s not found", inf.fragment), isError: true})
							mu.Unlock()
							return
						}
					}
					mu.Lock()
					pageLinks = append(pageLinks, linkResult{url: inf.display, status: st, isError: false})
					mu.Unlock()
					c.tryQueue(finalU.String(), b, hdr, &newWorks, &newWorksMu)
					return
				}
				st, hdr, b, finalU, eStr, _ := c.fetchWithRetriesFull(inf.display, "")
				if eStr != "" {
					mu.Lock()
					pageLinks = append(pageLinks, linkResult{url: inf.display, errStr: eStr, isError: true})
					mu.Unlock()
				} else {
					mu.Lock()
					pageLinks = append(pageLinks, linkResult{url: inf.display, status: st, isError: false})
					mu.Unlock()
					c.tryQueue(finalU.String(), b, hdr, &newWorks, &newWorksMu)
				}
			}(inf)
		}
		wg.Wait()
		sort.Slice(pageLinks, func(a, b int) bool {
			if pageLinks[a].isError != pageLinks[b].isError {
				return !pageLinks[a].isError
			}
			return pageLinks[a].url < pageLinks[b].url
		})
		pr := pageResult{url: pageURLStr, links: pageLinks}
		c.resultsMu.Lock()
		c.results = append(c.results, pr)
		c.resultsMu.Unlock()
		if c.opts.onePageOnly {
			break
		}
		for _, nw := range newWorks {
			queue = append(queue, nw)
		}
	}
	return c.results, ""
}
EOF
cat /workspace/crawl_loop.go | head -n 30
"}

