	out := TestSuites{TestSuites: suites}
	data, _ := xml.Marshal(out)
	// xml.Marshal does not include header, and escapes & etc. Need header `<?xml version="1.0" encoding="UTF-8"?>\n` + <testsuites>...
	// Observed header exactly: `<?xml version="1.0" encoding="UTF-8"?>\n<testsuites>\n  <testsuite ...`
	// Go's Marshal gives <testsuites><testsuite ...> without newlines/indentation. Observed has newlines and 2-space indent.
	// Need to format with indentation to match exactly.
	// Observed:
	// <?xml version="1.0" encoding="UTF-8"?>
	// <testsuites>
	//   <testsuite name="..." tests="..." failures="..." skipped="0">
	//     <testcase name="..." classname="..."></testcase>
	//     ...
	//     <testcase ...>
	//       <failure message="..."></failure>
	//     </testcase>
	//   </testsuite>
	// </testsuites>
	// Need to replicate exactly with 2-space indent.
	// Instead of using xml.Marshal with indent, we can manually build string to ensure exact.
	// Let's manually build.
	var sb strings.Builder
	sb.WriteString(`<?xml version="1.0" encoding="UTF-8"?>` + "\n")
	sb.WriteString("<testsuites>\n")
	for _, ts := range suites {
		// escape attrs
		nameEsc := xmlEscape(ts.Name)
		sb.WriteString(fmt.Sprintf("  <testsuite name=\"%s\" tests=\"%d\" failures=\"%d\" skipped=\"%d\"", nameEsc, ts.Tests, ts.Failures, ts.Skipped))
		if len(ts.TestCases) == 0 {
			sb.WriteString("></testsuite>\n")
		} else {
			sb.WriteString(">\n")
			for _, tc := range ts.TestCases {
				nEsc := xmlEscape(tc.Name)
				cEsc := xmlEscape(tc.Classname)
				if tc.Failure == nil {
					sb.WriteString(fmt.Sprintf("    <testcase name=\"%s\" classname=\"%s\"></testcase>\n", nEsc, cEsc))
				} else {
					mEsc := xmlEscape(tc.Failure.Message)
					sb.WriteString(fmt.Sprintf("    <testcase name=\"%s\" classname=\"%s\">\n", nEsc, cEsc))
					sb.WriteString(fmt.Sprintf("      <failure message=\"%s\"></failure>\n", mEsc))
					sb.WriteString("    </testcase>\n")
				}
			}
			sb.WriteString("  </testsuite>\n")
		}
	}
	sb.WriteString("</testsuites>\n")
	fmt.Printf("%s", sb.String())
	_ = data
}

func xmlEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&apos;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}
