    def log_message(self,*a): pass
    def do_GET(self):
        if self.path=="/" :
            body=b'<html><body><a href="/keep">k</a><a href="/skip">s</a></body></html>'
            self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
        elif self.path in ("/keep","/skip"):
            body=b'<html><body>ok</body></html>'; self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
        else:
            b=b'nf'; self.send_response(404); self.send_header("Content-Length",str(len(b))); self.end_headers(); self.wfile.write(b)

