		endTag := strings.Index(strings.ToLower(body[gt:]), "</loc>")
		if endTag == -1 {
			break
		}
		endTag += gt
		content := strings.TrimSpace(body[gt+1 : endTag])
		if content != "" {
			// strip fragment?
			content = stripFragment(strings.TrimSpace(content))
			m[content] = true
			// Also store without trailing slash variations? No, exact.
		}
		idx = endTag + 6
	}
	return m
}
